import numpy as np
from scipy.optimize import minimize
from scipy.spatial import Voronoi

N = 26

def generate_grid_hole_seed(hole_pos_idx):
    coords = [0.1, 0.3, 0.5, 0.7, 0.9]
    grid_centers = np.array([[x, y] for x in coords for y in coords])
    row_idx, col_idx = hole_pos_idx//5, hole_pos_idx%5
    hole_center = np.array([0.2 + row_idx*0.2, 0.2 + col_idx*0.2])
    return np.vstack([grid_centers, hole_center])

def voronoi_heuristic(centers):
    dummy_points = np.array([[5,5],[-5,5],[5,-5],[-5,-5],[0.5,5],[0.5,-5],[5,0.5],[-5,0.5]])
    vor = Voronoi(np.vstack([centers, dummy_points]))
    total_radius_sum = 0
    for i in range(N):
        point = vor.points[i]; region_idx = vor.point_region[i]
        vertices_indices = vor.regions[region_idx]
        if -1 in vertices_indices: return 0
        vertices = vor.vertices[vertices_indices]
        radius = min(point[0], 1-point[0], point[1], 1-point[1])
        for vertex in vertices: radius = min(radius, np.linalg.norm(point - vertex))
        total_radius_sum += radius
    return total_radius_sum

def construct_packing() -> tuple:
    np.random.seed(300)

    # --- Stage 1: Generate and Score Candidate Seeds ---
    CANDIDATE_POOL_SIZE = 300
    PERTURBATION_MAG = 0.04

    candidate_seeds = []
    for i in range(CANDIDATE_POOL_SIZE):
        grid_idx = np.random.randint(25)
        base_centers = generate_grid_hole_seed(grid_idx)
        perturbation = np.random.uniform(-PERTURBATION_MAG, PERTURBATION_MAG, size=base_centers.shape)
        perturbed_centers = np.clip(base_centers + perturbation, 0, 1)
        candidate_seeds.append(perturbed_centers)

    scored_seeds = [{'centers': c, 'score': voronoi_heuristic(c)} for c in candidate_seeds]
    scored_seeds.sort(key=lambda x: x['score'], reverse=True)

    best_seed_centers = scored_seeds[0]['centers']

    # For refinement, we need an estimated radius for the seed
    # We'll run a quick optimization on the seed itself first
    def cr_to_z(c, r): return np.concatenate([c.flatten(), r])
    def z_to_cr(z): return z[:N*2].reshape(N, 2), z[N*2:]
    def objective(z): return -np.sum(z[N*2:])
    def ineq_boundary(z):
        c, r = z_to_cr(z); return np.concatenate([c[:,0]-r, 1-(c[:,0]+r), c[:,1]-r, 1-(c[:,1]+r)])
    def ineq_nonoverlap(z):
        c, r = z_to_cr(z); diff = c[:, None, :] - c[None, :, :]; dist = np.sqrt(np.sum(diff**2, axis=-1))
        iu = np.triu_indices(N, 1); return dist[iu] - (r[iu[0]] + r[iu[1]])
    def _ensure_validity(c, r):
        for _ in range(10):
            v=0
            for i in range(N):
                for j in range(i + 1, N):
                    dist = np.linalg.norm(c[i] - c[j]); rad_sum = r[i] + r[j]
                    if dist < rad_sum: v+=1; scale = (dist/rad_sum)*(1.0-1e-9); r[i]*=scale; r[j]*=scale
            if v==0: break
        r_vec = r.reshape(-1, 1); c = np.clip(c, r_vec, 1.0 - r_vec)
        return c, np.maximum(r, 1e-6)

    initial_z = cr_to_z(best_seed_centers, np.full(N, 0.05))
    bounds = [(0,1)]*N*2 + [(1e-6, 0.5)]*N
    constraints = [{'type': 'ineq', 'fun': ineq_boundary}, {'type': 'ineq', 'fun': ineq_nonoverlap}]
    res = minimize(objective, initial_z, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter': 500, 'ftol': 1e-9})
    if res.success: base_centers, base_radii = _ensure_validity(*z_to_cr(res.x))
    else: base_centers, base_radii = _ensure_validity(best_seed_centers, np.full(N, 0.05))

    # --- Stage 2: Push-Pull Perturbation (from SOTA script) ---
    contacts, slacks = [], []
    for i in range(N):
        for j in range(i+1, N):
            dist = np.linalg.norm(base_centers[i] - base_centers[j]); slack = dist - (base_radii[i] + base_radii[j])
            if abs(slack) < 1e-6: contacts.append((i, j))
            elif slack > 0: slacks.append({'pair': (i, j), 'slack': slack})
    slacks.sort(key=lambda x: x['slack'])
    push_target = slacks[0]['pair'] if slacks else None
    pull_targets = []
    if push_target:
        c1, c2 = push_target
        for contact in contacts:
            if c1 in contact or c2 in contact: pull_targets.append(contact)

    perturbed_centers = np.copy(base_centers)
    if push_target:
        i, j = push_target; dist_vec = perturbed_centers[i] - perturbed_centers[j]
        grad = dist_vec / (np.linalg.norm(dist_vec) + 1e-9); move_amount = 5e-4
        perturbed_centers[i] += grad * move_amount; perturbed_centers[j] -= grad * move_amount
    for i, j in pull_targets:
        dist_vec = perturbed_centers[i] - perturbed_centers[j]
        grad = dist_vec / (np.linalg.norm(dist_vec) + 1e-9); move_amount = -5e-4
        perturbed_centers[i] += grad * move_amount; perturbed_centers[j] -= grad * move_amount

    # --- Stage 3: Jittered Refinement ---
    best_score = -np.inf; best_centers, best_radii = None, None
    jitter_amplitudes = [1e-4, 5e-4, 1e-3, 2e-3, 3e-3]
    for amp in jitter_amplitudes:
        for i in range(5):
            np.random.seed(int(amp*1e6)+i); jitter = np.random.uniform(-amp, amp, size=perturbed_centers.shape)
            initial_centers = np.clip(perturbed_centers + jitter, 1e-6, 1-1e-6)
            initial_z = cr_to_z(initial_centers, base_radii)
            res = minimize(objective, initial_z, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter': 500, 'ftol': 1e-9})
            if res.success:
                c, r = _ensure_validity(*z_to_cr(res.x)); score = np.sum(r)
                if score > best_score: best_score = score; best_centers, best_radii = c, r

    return best_centers if best_centers is not None else base_centers, best_radii if best_radii is not None else base_radii
